function isOnlineFromSeed(seed) {
    // Simple deterministic hash → 0..99 ; online if < 70
    let hash = 0;
    for(let i = 0; i < seed.length; i++){
        hash = (hash * 31 + seed.charCodeAt(i)) % 1000;
    }
    return hash % 100 < 70;
}
