function getStreakInsight(streak) {
    if (streak < 7) {
        return {
            textKey: "dailyInsightEarly",
            type: "early"
        };
    }
    if (streak < 30) {
        return {
            textKey: "dailyInsightRepair",
            type: "repair"
        };
    }
    if (streak < 90) {
        return {
            textKey: "dailyInsightControl",
            type: "control"
        };
    }
    return {
        textKey: "dailyInsightInspiration",
        type: "inspiration"
    };
}
function analyzeJournalEmotions(emotions) {
    if (emotions.length === 0) return null;
    const frustratedCount = emotions.filter((e)=>e.emotion === "frustrated" || e.emotion === "tempted").length;
    const positiveCount = emotions.filter((e)=>e.emotion === "calm" || e.emotion === "proud" || e.emotion === "strong").length;
    const avgIntensity = emotions.reduce((s, e)=>s + e.intensity, 0) / emotions.length;
    if (positiveCount > frustratedCount) {
        return {
            textKey: "dailyInsightJournalPositive",
            type: "journal"
        };
    }
    if (frustratedCount > positiveCount && avgIntensity > 3) {
        return {
            textKey: "dailyInsightJournalTension",
            type: "journal"
        };
    }
    return {
        textKey: "dailyInsightJournalDefault",
        type: "journal"
    };
}
